<section class="service-panel permit-history-panel permit-records-panel" id="<?= $tabKey === 'history' ? 'permitHistory' : 'permitRequests' ?>" aria-labelledby="permitRecordsTitle-<?= $tabKey ?>" data-permit-list>
<header class="permit-panel-heading"><div><h2 id="permitRecordsTitle-<?= $tabKey ?>"><?= $tabKey === 'history' ? 'Permit history' : ($staffServices ? 'Permit requests' : 'Your permit requests') ?></h2><p><?= $tabKey === 'history' ? 'View completed, rejected, cancelled and expired permits.' : 'Track active requests, requested changes and approved permits.' ?></p></div></header>
<div class="service-form permit-filters"><label class="field-label">Search permits<input type="search" id="permitSearch-<?= $tabKey ?>" data-permit-search placeholder="Permit number, requester or unit"></label><label class="field-label">Status<select id="permitStatusFilter-<?= $tabKey ?>" data-permit-status-filter><option value="">All statuses</option><?php foreach($tabKey === 'history' ? ['rejected','cancelled','expired','completed'] : ['pending','changes_requested','approved'] as $status): ?><option value="<?= $status ?>"><?= serviceEscape(ucfirst(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select></label></div>
<?php if(!$permitRecords): ?><p class="service-empty-state"><?= $tabKey === 'history' ? 'No past permit requests yet.' : 'No active permit requests. Submitted permits will appear here.' ?></p><?php else: ?><div class="permit-table-wrap"><table class="permit-table"><thead><tr><th>Permit number / type</th><?php if($staffServices): ?><th>Requester / Unit</th><?php endif; ?><th>Items</th><th>Schedule</th><th>Submitted</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($permitRecords as $request): $property=!empty($request['gate_data']); $data=$property?gateData($request):[]; $status=permitWorkspaceStatus($request); $schedule=$data['authorized'] ?? $data['requested'] ?? null; ?>
<tr data-permit-status="<?= serviceEscape($status) ?>"><td data-label="Permit"><div class="permit-cell-value"><strong><?= $property?gateNumber((int)$request['id']):'#'.(int)$request['id'] ?></strong><br><?= serviceEscape($request['permit_type']) ?><?= $property?'<br>'.($data['direction']==='entry'?'Bring In':'Pull-Out'):'' ?></div></td>
<?php if($staffServices): ?><td data-label="Requester / Unit"><div class="permit-cell-value"><?= serviceEscape($request['full_name']) ?><br>Unit <?= serviceEscape($request['unit_number']) ?></div></td><?php endif; ?>
<td data-label="Items"><div class="permit-cell-value"><?= $property?(int)$request['item_count']:'—' ?></div></td><td data-label="Schedule"><div class="permit-cell-value"><?= serviceEscape($schedule['date'] ?? $request['start_date']) ?><?php if($schedule): ?><br><?= serviceEscape($schedule['start'].' – '.$schedule['end']) ?><?php else: ?><br>to <?= serviceEscape($request['end_date']) ?><?php endif; ?></div></td><td data-label="Submitted"><div class="permit-cell-value"><?= serviceEscape($request['created_at']) ?></div></td><td data-label="Status"><div class="permit-cell-value"><span class="service-status service-status-<?= serviceEscape($status) ?>"><?= serviceEscape(ucfirst(str_replace('_',' ',$status))) ?></span></div></td>
<td class="permit-actions-cell" data-label="Actions"><div class="permit-table-actions"><a class="service-btn service-btn-secondary" href="<?= $staffServices?'service_requests.php?kind=permit&amp;':'permits.php?' ?>request_id=<?= (int)$request['id'] ?>">View details</a>
<?php if(!$staffServices && $property && $status==='changes_requested'): ?><a class="service-btn" href="permits.php?request_id=<?= (int)$request['id'] ?>&amp;edit=1">Edit / resubmit</a><?php endif; ?>
<?php if($status==='approved'): ?><a class="service-btn service-btn-secondary" href="<?= serviceEscape(residentServicePassUrl($request)) ?>"><?= !$staffServices ? ($property?'View / download gate pass':'View / download permit') : ($property?'View gate pass':'View permit') ?></a><?php endif; ?>
<?php if($property && in_array($status,['pending','changes_requested','approved'],true)): ?><form method="post" action="<?= serviceEscape($permitListAction) ?>" data-confirm="Cancel this permit request?"><?= workflowCsrfField() ?><input type="hidden" name="action" value="gate_cancelled"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="service-btn service-btn-danger">Cancel request</button></form><?php elseif(!$property && !$staffServices && in_array($status,['pending','approved'],true)): ?><form method="post" action="<?= serviceEscape($permitListAction) ?>" data-confirm="Cancel this permit request?"><?= workflowCsrfField() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button class="service-btn service-btn-danger">Cancel request</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><p id="permitNoMatches-<?= $tabKey ?>" data-permit-no-matches hidden>No permits match your search.</p><?php endif; ?></section>
